function pagedKvCache(host) {
    var state = { seq: 70, page: 16 };
    var W = 520, H = 210, PAD = 18;
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var num = el('span', { class: 'lf-num' });
    var bar = el('i');
    var barWrap = el('div', { class: 'lf-bar' }, [bar]);
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    var SLOTS = 128; // a contiguous reservation must over-allocate to max length
    var MAXLEN = 128;
    state._render = function () {
      var seq = state.seq, page = state.page;
      var pages = Math.ceil(seq / page);
      var paged = pages * page;
      var pagedWaste = paged - seq;
      var contigWaste = MAXLEN - seq; // contiguous reserves the full max up front
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var cols = 32, cw = (W - 2 * PAD) / cols, ch = 12;
      // contiguous row: one reservation of MAXLEN, used part blue, reserved-but-empty grey
      var rowY = 40, i;
      var ttop = svgEl('text', { x: PAD, y: (rowY - 8).toFixed(1), 'font-family': 'monospace', 'font-size': '10', fill: 'var(--ink-mute,#777)' });
      ttop.appendChild(document.createTextNode('contiguous: reserve max length up front'));
      svg.appendChild(ttop);
      for (i = 0; i < MAXLEN; i++) {
        var cx = PAD + (i % cols) * cw, cy = rowY + Math.floor(i / cols) * (ch + 2);
        svg.appendChild(svgEl('rect', { x: cx.toFixed(1), y: cy.toFixed(1), width: (cw - 2).toFixed(1), height: ch, rx: '1',
          fill: i < seq ? 'var(--blueprint,#3553ff)' : 'var(--rule-soft,#ccc)', opacity: i < seq ? '0.9' : '0.5' }));
      }
      // paged row: pages allocated on demand, only the last page partly wasted
      var rowY2 = rowY + 4 * (ch + 2) + 30;
      var tbot = svgEl('text', { x: PAD, y: (rowY2 - 8).toFixed(1), 'font-family': 'monospace', 'font-size': '10', fill: 'var(--ink-mute,#777)' });
      tbot.appendChild(document.createTextNode('paged: ' + pages + ' pages of ' + page + ', only the last partly free'));
      svg.appendChild(tbot);
      for (i = 0; i < paged; i++) {
        var px2 = PAD + (i % cols) * cw, py2 = rowY2 + Math.floor(i / cols) * (ch + 2);
        var usedCell = i < seq;
        svg.appendChild(svgEl('rect', { x: px2.toFixed(1), y: py2.toFixed(1), width: (cw - 2).toFixed(1), height: ch, rx: '1',
          fill: usedCell ? 'var(--blueprint,#3553ff)' : 'var(--warn,#b8870f)', opacity: usedCell ? '0.9' : '0.55' }));
        if (i % page === 0) {
          svg.appendChild(svgEl('line', { x1: px2.toFixed(1), y1: py2.toFixed(1), x2: px2.toFixed(1), y2: (py2 + ch).toFixed(1), stroke: 'var(--ink,#1a1a1a)', 'stroke-width': '1' }));
        }
      }
      var savedPct = Math.round((1 - paged / MAXLEN) * 100);
      num.innerHTML = pagedWaste + ' <small>cells wasted (paged)</small>';
      bar.style.width = Math.max(2, Math.min(100, savedPct)) + '%';
      meta.textContent = 'contiguous wastes ' + contigWaste + ' reserved cells · paged wastes only ' + pagedWaste
        + ' (last page) · ' + savedPct + '% less reserved memory';
      formula.textContent = 'pages = ⌈seq / page⌉ = ⌈' + seq + ' / ' + page + '⌉ = ' + pages
        + '  ·  internal waste ≤ page − 1 per sequence, not max − seq';
    };
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'seq', 'sequence length', 1, MAXLEN, 1),
      slider(state, 'page', 'page (block) size', 4, 32, 4)
    ]);
    host.appendChild(el('div', { class: 'lf' }, [
      el('div', { class: 'lf-head' }, [el('span', { class: 'lf-label' }, ['PAGED KV CACHE']), el('span', {}, ['drag length and page size'])]),
      el('div', { class: 'lf-body' }, [grid, el('div', { class: 'lf-out' }, [svg, num, barWrap, meta, formula])]),
      el('div', { class: 'lf-cap' }, ['A contiguous KV cache reserves the full maximum sequence length per request up front, so most of it sits empty (grey). PagedAttention stores the cache in fixed-size pages allocated on demand: only the final page is partly free (orange). Internal waste drops from max minus length to at most one page, which is why paged caches fit far more concurrent sequences on the same GPU.'])
    ]));
    state._render();
  }

function quantization(host) {
    var state = { logN: 9.85, bits: 16 };
    var num = el('span', { class: 'lf-num' });
    var bar = el('i');
    var barWrap = el('div', { class: 'lf-bar' }, [bar]);
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    var GB = 1e9;
    function human(x) { var u = ['', 'K', 'M', 'B', 'T']; var i = 0; while (x >= 1000 && i < u.length - 1) { x /= 1000; i++; } return x.toFixed(x < 10 ? 1 : 0) + u[i]; }
    state._render = function () {
      var N = Math.pow(10, state.logN);
      var bytesFp32 = N * 4;
      var bytes = N * state.bits / 8;
      var gb = bytes / GB;
      num.innerHTML = gb.toFixed(gb < 10 ? 2 : 1) + ' <small>GB</small>';
      bar.style.transform = 'scaleX(' + Math.min(1, state.bits / 32) + ')';
      var levels = Math.pow(2, state.bits);
      var err = state.bits >= 16 ? 'negligible' : state.bits >= 8 ? '< 1% perplexity hit' : state.bits >= 4 ? 'small with good schemes (GPTQ/AWQ)' : 'large: needs care';
      meta.textContent = Math.round((1 - bytes / bytesFp32) * 100) + '% smaller than fp32  ·  quantization error: ' + err;
      formula.textContent = human(N) + ' params · ' + state.bits + ' bits = ' + (state.bits >= 16 ? '2^' + state.bits : human(levels)) + ' levels per weight';
    };
    var sel = el('select');
    [['fp32 (32-bit)', 32], ['fp16 / bf16 (16-bit)', 16], ['int8 (8-bit)', 8], ['int4 (4-bit)', 4], ['int2 (2-bit)', 2]].forEach(function (o) { sel.appendChild(el('option', { value: o[1] }, [o[0]])); });
    sel.value = state.bits;
    sel.addEventListener('change', function () { state.bits = Number(sel.value); state._render(); });
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'logN', 'parameters (10^x)', 8, 12, 0.05),
      el('div', { class: 'lf-ctrl' }, [el('label', {}, ['precision']), sel])
    ]);
    host.appendChild(el('div', { class: 'lf' }, [
      el('div', { class: 'lf-head' }, [el('span', { class: 'lf-label' }, ['QUANTIZATION']), el('span', {}, ['pick the precision'])]),
      el('div', { class: 'lf-body' }, [grid, el('div', { class: 'lf-out' }, [num, barWrap, meta, formula])]),
      el('div', { class: 'lf-cap' }, ['Each weight costs its bit-width in storage. Halving the bits halves the memory and roughly doubles throughput, while the precision lost grows. 8-bit is nearly free; 4-bit needs careful schemes; below that, accuracy falls off.'])
    ]));
    state._render();
  }

function contextWindowSlide(host) {
    var state = { seq: 14, window: 8 };
    var W = 520, H = 130, PAD = 20;
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var num = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    var MAX = 24;
    state._render = function () {
      var n = state.seq, win = state.window;
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var firstKept = Math.max(0, n - win);
      var cw = (W - 2 * PAD) / MAX;
      var bw = cw * 0.82, gap = cw * 0.18;
      var y = PAD + 18;
      var i;
      for (i = 0; i < n; i++) {
        var x = PAD + i * cw + gap / 2;
        var inWin = i >= firstKept;
        svg.appendChild(svgEl('rect', { x: x.toFixed(1), y: y, width: bw.toFixed(1), height: '28', rx: '2',
          fill: inWin ? 'var(--blueprint,#3553ff)' : 'var(--rule-soft,#ccc)',
          opacity: inWin ? '1' : '0.6' }));
      }
      // window bracket
      var wx0 = PAD + firstKept * cw, wx1 = PAD + n * cw;
      svg.appendChild(svgEl('rect', { x: wx0.toFixed(1), y: (y - 8).toFixed(1),
        width: (wx1 - wx0).toFixed(1), height: '44', fill: 'none',
        stroke: 'var(--warn,#b8870f)', 'stroke-width': '1.5' }));
      var dropped = Math.max(0, n - win);
      num.innerHTML = dropped + ' <small>tokens dropped</small>';
      meta.textContent = 'sequence ' + n + ' tokens · window ' + win + '  ·  '
        + (dropped > 0 ? 'oldest ' + dropped + ' fall outside the rolling context' : 'everything still fits');
      formula.textContent = 'attention sees only the last ' + win + ' positions; tokens before index '
        + firstKept + ' are no longer attended to';
    };
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'seq', 'sequence length', 1, MAX, 1),
      slider(state, 'window', 'context window', 1, 16, 1)
    ]);
    host.appendChild(el('div', { class: 'lf' }, [
      el('div', { class: 'lf-head' }, [el('span', { class: 'lf-label' }, ['CONTEXT WINDOW']), el('span', {}, ['drag length past the window'])]),
      el('div', { class: 'lf-body' }, [grid, el('div', { class: 'lf-out' }, [svg, num, meta, formula])]),
      el('div', { class: 'lf-cap' }, ['A model can only attend over a fixed window. As the sequence grows past it, the oldest tokens slide out of the orange frame and are no longer visible to attention. This is the rolling context: recent tokens stay, early ones are forgotten unless they are summarized or retrieved back in.'])
    ]));
    state._render();
  }

function specDecode(host) {
    var svg = svgEl('svg', { viewBox: '0 0 520 220' });
    var g = svgEl('g');
    g.appendChild(box(8, 88, 50, 26, MUTE));
    g.appendChild(txt(33, 105, 'draft', 9, MUTE, 'middle'));
    g.appendChild(box(160, 16, 220, 26, INK, 'none', 1.4));
    g.appendChild(txt(270, 33, 'verifier: one forward pass', 9.5, INK, 'middle'));
    var sweep = svgEl('rect', { x: 66, y: 80, width: 78, height: 42, fill: BP, opacity: 0 });
    sweep.appendChild(anim('x', '66;66;320;320', '5.5s', { calcMode: 'linear', keyTimes: '0;0.28;0.52;1' }));
    sweep.appendChild(anim('opacity', '0;0;0.16;0.16;0;0', '5.5s', { keyTimes: '0;0.26;0.3;0.52;0.58;1' }));
    g.appendChild(sweep);
    var slotX = [70, 154, 238, 322];
    var appear = ['0;0.05;0.09;0.93;1', '0;0.095;0.135;0.93;1', null, null];
    var i;
    for (i = 0; i < 4; i++) {
      var gs = svgEl('g', { opacity: 0 });
      gs.appendChild(svgEl('rect', { x: slotX[i], y: 84, width: 70, height: 34, rx: 4, fill: 'none', stroke: MUTE, 'stroke-width': 1.2, 'stroke-dasharray': '4 3' }));
      gs.appendChild(txt(slotX[i] + 35, 106, 'd' + (i + 1), 10, SOFT, 'middle'));
      if (i < 2) {
        gs.appendChild(anim('opacity', '0;0;0.9;0.9;0', '5.5s', { keyTimes: appear[i] }));
      } else {
        var s0 = i === 2 ? '0.14' : '0.185', s1 = i === 2 ? '0.18' : '0.225';
        var e0 = i === 2 ? '0.56' : '0.5', e1 = i === 2 ? '0.62' : '0.56';
        gs.appendChild(anim('opacity', '0;0;0.9;0.9;0;0', '5.5s', { keyTimes: '0;' + s0 + ';' + s1 + ';' + e0 + ';' + e1 + ';1' }));
      }
      g.appendChild(gs);
    }
    var accTimes = ['0;0.34;0.38;0.93;1', '0;0.42;0.46;0.93;1'];
    for (i = 0; i < 2; i++) {
      var acc = svgEl('rect', { x: slotX[i], y: 84, width: 70, height: 34, rx: 4, fill: BP, opacity: 0 });
      acc.appendChild(anim('opacity', '0;0;0.5;0.5;0', '5.5s', { keyTimes: accTimes[i] }));
      g.appendChild(acc);
    }
    var xm = svgEl('path', { d: 'M 263 91 L 283 111 M 283 91 L 263 111', stroke: WARN, 'stroke-width': 2, fill: 'none', opacity: 0 });
    xm.appendChild(anim('opacity', '0;0;1;1;0;0', '5.5s', { keyTimes: '0;0.5;0.53;0.58;0.63;1' }));
    g.appendChild(xm);
    var fix = svgEl('g', { opacity: 0 });
    fix.appendChild(svgEl('rect', { x: 238, y: 84, width: 70, height: 34, rx: 4, fill: BP }));
    fix.appendChild(txt(273, 106, 'resample', 8.5, 'var(--bg,#fafaf5)', 'middle'));
    fix.appendChild(anim('opacity', '0;0;1;1;0', '5.5s', { keyTimes: '0;0.6;0.66;0.93;1', calcMode: 'spline', keySplines: EASE + ';' + EASE + ';' + EASE + ';' + EASE }));
    g.appendChild(fix);
    g.appendChild(txt(260, 190, 'two accepted + one corrected token from a single verifier forward', 9, MUTE, 'middle'));
    entry(g, 260, 110);
    svg.appendChild(g);
    card(host, 'SPECULATIVE DECODING', 'draft cheap, verify once', svg,
      'The draft head proposes four cheap tokens. One verifier forward pass scores all of them at once: the agreeing prefix is accepted, the first disagreement is rejected and replaced by a sample from the residual distribution, and everything after it is discarded. On a full accept the verifier emits a bonus token, so one big-model pass can yield N+1 tokens with the verifier distribution preserved exactly.');
  }

presentation_helpers.source:
function anim(attr, vals, dur, extra) {
    var a = { attributeName: attr, values: vals, dur: dur, repeatCount: 'indefinite' };
    if (extra) { for (var k in extra) { a[k] = extra[k]; } }
    return svgEl('animate', a);
  }

function txt(x, y, s, size, fill, anchor) {
    var a = { x: x, y: y, 'font-family': MONO, 'font-size': size, fill: fill };
    if (anchor) { a['text-anchor'] = anchor; }
    var t = svgEl('text', a);
    t.appendChild(document.createTextNode(s));
    return t;
  }

function box(x, y, w, h, stroke, fill, sw) {
    return svgEl('rect', { x: x, y: y, width: w, height: h, rx: 4, fill: fill || 'none', stroke: stroke, 'stroke-width': sw || 1.3 });
  }

function entry(g, cx, cy) {
    var common = { dur: '0.7s', begin: '0s', fill: 'freeze', repeatCount: '1', calcMode: 'spline', keyTimes: '0;1', keySplines: EASE };
    g.setAttribute('opacity', '0');
    var o = { attributeName: 'opacity', values: '0;1' }, k;
    for (k in common) { o[k] = common[k]; }
    g.appendChild(svgEl('animate', o));
    var t = { attributeName: 'transform', type: 'translate', values: (cx * 0.05).toFixed(1) + ' ' + (cy * 0.05).toFixed(1) + ';0 0' };
    for (k in common) { t[k] = common[k]; }
    g.appendChild(svgEl('animateTransform', t));
    var s = { attributeName: 'transform', type: 'scale', values: '0.95;1', additive: 'sum' };
    for (k in common) { s[k] = common[k]; }
    g.appendChild(svgEl('animateTransform', s));
    return g;
  }

function card(host, label, sub, svg, cap) {
    host.appendChild(el('div', { class: 'lf' }, [
      el('div', { class: 'lf-head' }, [el('span', { class: 'lf-label' }, [label]), el('span', {}, [sub])]),
      el('div', { class: 'lf-body' }, [el('div', { class: 'lf-out' }, [svg])]),
      el('div', { class: 'lf-cap' }, [cap])
    ]));
  }

