function expertCapacity(host) {
    var state = { cap: 1.25, tokens: 64 };
    var W = 520, H = 200, PAD = 24, E = 8;
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var num = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    // deterministic skewed routing: expert e gets a fixed share of tokens
    var SHARE = [0.22, 0.18, 0.15, 0.13, 0.11, 0.09, 0.07, 0.05];
    state._render = function () {
      var T = state.tokens, cap = state.cap;
      var perExpert = Math.floor(cap * T / E); // capacity slots per expert
      var loads = SHARE.map(function (s) { return Math.round(s * T); });
      var sum = loads.reduce(function (a, b) { return a + b; }, 0);
      loads[0] += (T - sum); // keep total exactly T
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var bw = (W - 2 * PAD) / E - 8, dropped = 0, wasted = 0, e;
      var maxBar = H - 2 * PAD;
      var capRef = Math.max(1, Math.max.apply(null, loads), perExpert);
      var capY = H - PAD - perExpert / capRef * maxBar;
      for (e = 0; e < E; e++) {
        var x = PAD + e * ((W - 2 * PAD) / E) + 4;
        var load = loads[e];
        var routed = Math.min(load, perExpert);
        var over = Math.max(0, load - perExpert);
        dropped += over; wasted += Math.max(0, perExpert - load);
        var hUsed = routed / capRef * maxBar;
        svg.appendChild(svgEl('rect', { x: x.toFixed(1), y: (H - PAD - hUsed).toFixed(1), width: bw.toFixed(1), height: hUsed.toFixed(1), fill: 'var(--blueprint,#3553ff)', opacity: '0.9' }));
        if (over > 0) {
          var hOver = over / capRef * maxBar;
          svg.appendChild(svgEl('rect', { x: x.toFixed(1), y: (H - PAD - hUsed - hOver).toFixed(1), width: bw.toFixed(1), height: hOver.toFixed(1), fill: 'var(--warn,#b8870f)', opacity: '0.7' }));
        }
      }
      svg.appendChild(svgEl('line', { x1: PAD, y1: capY.toFixed(1), x2: W - PAD, y2: capY.toFixed(1), stroke: 'var(--ink,#1a1a1a)', 'stroke-width': '1', 'stroke-dasharray': '4 3' }));
      num.innerHTML = dropped + ' <small>tokens dropped</small>';
      meta.textContent = 'capacity ' + perExpert + ' / expert · dropped ' + dropped + ' (overflow, orange) · idle ' + wasted
        + ' slots (wasted compute) · ' + (cap < 1 ? 'too tight' : cap > 1.5 ? 'too loose' : 'balanced');
      formula.textContent = 'capacity = ⌊capacity_factor · tokens / experts⌋ = ⌊' + cap.toFixed(2) + ' · ' + T + ' / ' + E + '⌋ = ' + perExpert;
    };
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'cap', 'capacity factor', 0.5, 2.0, 0.05),
      slider(state, 'tokens', 'tokens in batch', 16, 128, 8)
    ]);
    host.appendChild(el('div', { class: 'lf' }, [
      el('div', { class: 'lf-head' }, [el('span', { class: 'lf-label' }, ['EXPERT CAPACITY']), el('span', {}, ['drag capacity and tokens'])]),
      el('div', { class: 'lf-body' }, [grid, el('div', { class: 'lf-out' }, [svg, num, meta, formula])]),
      el('div', { class: 'lf-cap' }, ['Each expert in an MoE layer gets a fixed number of token slots, set by the capacity factor. Routing is uneven, so popular experts overflow and the extra tokens are dropped (orange above the dashed line). Set the factor too low and you drop many tokens; set it too high and lightly-loaded experts sit idle, wasting padded compute. The factor is tuned to keep both small.'])
    ]));
    state._render();
  }

function continuousBatching(host) {
    var state = { mode: 'continuous', slots: 4 };
    var W = 520, H = 200, PAD = 26;
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var num = el('span', { class: 'lf-num' });
    var bar = el('i');
    var barWrap = el('div', { class: 'lf-bar' }, [bar]);
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    // request lengths (in steps) arriving for the slots, deterministic
    var LENS = [3, 7, 2, 9, 4, 6, 5, 8, 3, 7];
    var STEPS = 12;
    state._render = function () {
      var S = state.slots;
      while (svg.firstChild) svg.removeChild(svg.firstChild);
      var rowH = (H - 2 * PAD) / S, cw = (W - 2 * PAD) / STEPS;
      var busy = 0, total = S * STEPS;
      var queue = LENS.slice(S); // remaining requests after the first S
      var qi = 0;
      var r;
      for (r = 0; r < S; r++) {
        var y = PAD + r * rowH + 2;
        var t = 0;
        var curLen = LENS[r];
        var start = 0;
        while (t < STEPS) {
          // run current request for curLen steps from start
          var runEnd = Math.min(STEPS, start + curLen);
          var x = PAD + start * cw;
          svg.appendChild(svgEl('rect', { x: x.toFixed(1), y: y.toFixed(1),
            width: ((runEnd - start) * cw - 2).toFixed(1), height: (rowH - 4).toFixed(1), rx: '2',
            fill: 'var(--blueprint,#3553ff)', opacity: '0.85' }));
          busy += (runEnd - start);
          t = runEnd;
          if (state.mode === 'continuous' && qi < queue.length) {
            // immediately refill the freed slot with the next queued request
            start = t; curLen = queue[qi++];
          } else {
            // static: slot idles until the whole batch finishes at max length
            break;
          }
        }
      }
      var util;
      if (state.mode === 'static') {
        // static batch runs until the longest request in the first batch ends
        var maxLen = Math.max.apply(null, LENS.slice(0, S));
        var work = 0, k;
        for (k = 0; k < S; k++) { work += Math.min(STEPS, LENS[k]); }
        util = work / (S * Math.min(STEPS, maxLen));
        // draw idle tails (grey) for static
        for (r = 0; r < S; r++) {
          var ll = Math.min(STEPS, LENS[r]);
          var maxl = Math.min(STEPS, maxLen);
          if (ll < maxl) {
            var yy = PAD + r * rowH + 2;
            svg.appendChild(svgEl('rect', { x: (PAD + ll * cw).toFixed(1), y: yy.toFixed(1),
              width: ((maxl - ll) * cw - 2).toFixed(1), height: (rowH - 4).toFixed(1), rx: '2',
              fill: 'var(--rule-soft,#ccc)', opacity: '0.7' }));
          }
        }
      } else {
        util = busy / total;
      }
      var pct = Math.round(util * 100);
      num.innerHTML = pct + ' <small>% GPU utilization</small>';
      bar.style.width = pct + '%';
      barWrap.classList.toggle('over', pct < 60);
      meta.textContent = state.mode === 'continuous'
        ? 'finished slots are refilled from the queue immediately, so the batch stays full'
        : 'every slot waits for the longest request in the batch before any new one starts';
      formula.textContent = 'utilization = busy slot-steps / total slot-steps  ·  ' + S + ' slots over ' + STEPS + ' steps';
    };
    var sel = LF.select(state, 'mode', 'batching', [['continuous', 'continuous'], ['static', 'static']]);
    var grid = el('div', { class: 'lf-grid' }, [
      sel,
      slider(state, 'slots', 'GPU slots', 2, 6, 1)
    ]);
    host.appendChild(el('div', { class: 'lf' }, [
      el('div', { class: 'lf-head' }, [el('span', { class: 'lf-label' }, ['CONTINUOUS BATCHING']), el('span', {}, ['toggle static vs continuous'])]),
      el('div', { class: 'lf-body' }, [grid, el('div', { class: 'lf-out' }, [svg, num, barWrap, meta, formula])]),
      el('div', { class: 'lf-cap' }, ['Requests in a batch finish at different times because they generate different numbers of tokens. Static batching holds every slot until the longest request ends, leaving grey idle time. Continuous batching refills each freed slot from the queue the moment it opens, keeping the GPU full and lifting utilization.'])
    ]));
    state._render();
  }

function speculativeDecoding(host) {
    var state = { gamma: 4, accept: 0.7 };
    var rows = el('div', {});
    var num = el('span', { class: 'lf-num' });
    var meta = el('div', { class: 'lf-meta' });
    var formula = el('div', { class: 'lf-formula' });
    state._render = function () {
      var g = state.gamma, a = state.accept;
      // expected accepted prefix length before first rejection (verifier still
      // emits one correction token), capped at g; plus the bonus token if all g pass
      var expAcc = 0, prob = 1, i;
      for (i = 1; i <= g; i++) { expAcc += prob * a; prob *= a; }
      var allPass = Math.pow(a, g);
      // tokens produced per verify pass: accepted run + 1 (correction or bonus)
      var tokensPerPass = expAcc + 1;
      // one verify pass replaces tokensPerPass sequential target steps
      var speedup = tokensPerPass;
      while (rows.firstChild) rows.removeChild(rows.firstChild);
      // visual row of g draft tokens: accepted (blue) up to floor(expAcc), then one verify token
      var acceptedShown = Math.min(g, Math.round(expAcc));
      var strip = el('div', { class: 'lf-grid' });
      for (i = 0; i < g; i++) {
        var on = i < acceptedShown;
        var b = el('i'); b.style.width = '100%';
        if (!on) b.style.background = 'var(--rule-soft,#ccc)';
        var lab = el('label', {}, ['draft ' + (i + 1), el('b', {}, [on ? 'accept' : 'reject'])]);
        if (!on) lab.style.opacity = '0.45';
        strip.appendChild(el('div', { class: 'lf-ctrl' }, [lab, el('div', { class: 'lf-bar' }, [b])]));
      }
      rows.appendChild(strip);
      num.innerHTML = speedup.toFixed(2) + ' <small>x tokens / verify pass</small>';
      meta.textContent = 'expected ' + expAcc.toFixed(2) + ' of ' + g + ' drafts accepted  ·  all-' + g
        + '-pass chance ' + (allPass * 100).toFixed(0) + '%  ·  + 1 token from the target each pass';
      formula.textContent = 'draft γ = ' + g + ' tokens, verify in one target pass, accept rate α = ' + a.toFixed(2)
        + '  →  ~' + speedup.toFixed(2) + ' tokens per target call';
    };
    var grid = el('div', { class: 'lf-grid' }, [
      slider(state, 'gamma', 'draft length γ', 1, 8, 1),
      slider(state, 'accept', 'acceptance rate α', 0.1, 0.99, 0.01)
    ]);
    host.appendChild(el('div', { class: 'lf' }, [
      el('div', { class: 'lf-head' }, [el('span', { class: 'lf-label' }, ['SPECULATIVE DECODING']), el('span', {}, ['drag draft and accept rate'])]),
      el('div', { class: 'lf-body' }, [grid, el('div', { class: 'lf-out' }, [rows, num, meta, formula])]),
      el('div', { class: 'lf-cap' }, ['A small draft model proposes γ tokens cheaply; the large target model verifies them all in a single parallel pass and accepts the longest correct prefix, then emits one more token itself. The higher the agreement rate, the longer the accepted run, and the more target calls each pass replaces.'])
    ]));
    state._render();
  }

function activationRecompute(host) {
    var W = 520, H = 220;
    var svg = svgEl('svg', { viewBox: '0 0 ' + W + ' ' + H });
    var n = 8, bw = 46, gap = 10, x0 = 50, fy = 60, by = 140;
    svg.appendChild(svgEl('text', { x: 8, y: fy + 18, 'font-family': 'var(--font-mono,monospace)', 'font-size': 9, fill: MUTE }, [document.createTextNode('FWD')]));
    svg.appendChild(svgEl('text', { x: 8, y: by + 18, 'font-family': 'var(--font-mono,monospace)', 'font-size': 9, fill: BP }, [document.createTextNode('BWD')]));
    var ckpt = { 0: 1, 3: 1, 6: 1 }; // layers whose activations are kept
    for (var i = 0; i < n; i++) {
      var x = x0 + i * (bw + gap);
      var kept = ckpt[i];
      // forward pass: every layer computed, only checkpoints stay solid
      var f = svgEl('rect', { x: x, y: fy, width: bw, height: 30, rx: 3,
        fill: kept ? BP : SOFT, stroke: kept ? BP : MUTE, 'stroke-width': 1, opacity: kept ? 0.85 : 1 });
      if (!kept) {
        // non-checkpoint activations fade away (dropped to save memory)
        f.appendChild(anim('opacity', '1;1;0.12;0.12', '5s', { keyTimes: '0;0.28;0.36;1' }));
      }
      svg.appendChild(f);
      if (kept) svg.appendChild(svgEl('text', { x: x + bw / 2, y: fy - 6, 'text-anchor': 'middle', 'font-family': 'var(--font-mono,monospace)', 'font-size': 8, fill: BP }, [document.createTextNode('save')]));
      // backward pass slot
      svg.appendChild(svgEl('rect', { x: x, y: by, width: bw, height: 30, rx: 3, fill: 'none', stroke: SOFT, 'stroke-width': 1 }));
    }
    // backward sweep: recompute dropped layers from the nearest checkpoint, right to left
    var rc = svgEl('rect', { x: 0, y: by, width: bw, height: 30, rx: 3, fill: WARN, opacity: 0.5 });
    rc.appendChild(anim('x', (x0 + (n - 1) * (bw + gap)) + ';' + x0, '5s', { keyTimes: '0;1', begin: '0s', calcMode: 'linear' }));
    rc.appendChild(anim('opacity', '0;0;0.55;0.55;0', '5s', { keyTimes: '0;0.45;0.5;0.95;1' }));
    svg.appendChild(rc);
    svg.appendChild(svgEl('text', { x: W / 2, y: by + 52, 'text-anchor': 'middle', 'font-family': 'var(--font-mono,monospace)',
      'font-size': 10, fill: MUTE }, [document.createTextNode('recompute dropped activations during backward')]));
    card(host, 'GRADIENT CHECKPOINTING', 'trade FLOPs for memory',
      svg, 'Backward needs the forward activations, but keeping them all blows the memory budget. Checkpointing saves only a few layers (solid) and discards the rest. During backward, each dropped segment is recomputed from the nearest checkpoint — a little extra compute buys a large drop in peak memory.');
  }

